/* User-triggered offline audio diagnostic; never requests microphone or MIDI access. */
$('#audioCheck').onclick=async()=>{const button=$('#audioCheck'),report=$('#audioCheckState');button.disabled=true;report.textContent='Vérification…';try{$('#audioTiming').textContent=typeof audioTimingInfo==='function'?audioTimingInfo(ctx):'';const c=new OfflineAudioContext(2,4096,44100);if(!await PocketLoFi.prepare(c))throw Error('Audio avancé indisponible ici : ouvrez la version HTTPS dans un navigateur récent.');const input=c.createBuffer(2,4096,44100),source=c.createBufferSource();for(let ch=0;ch<2;ch++)for(let i=0;i<input.length;i++)input.getChannelData(ch)[i]=(ch?-.5:.75)*Math.sin(i*.13+.2);source.buffer=input;const graph=PocketLoFi.create(c,source,c.destination,{bits:8,decimation:100});await graph.ready;source.start();const result=await c.startRendering();graph.dispose();let changes=0;for(let ch=0;ch<2;ch++){const a=result.getChannelData(ch);for(let i=0;i<a.length;i++){const expected=Math.round(input.getChannelData(ch)[Math.floor(i/128)*128]*128)/128;if(!Number.isFinite(a[i])||Math.abs(a[i]-expected)>1e-6)throw Error('Le rendu audio avancé ne correspond pas au résultat attendu.');if(i&&a[i]!==a[i-1])changes++}}if(!changes)throw Error('Aucun signal détecté.');report.textContent='Audio vérifié · traitement stéréo et export LoFi opérationnels. Aucun accès micro ou MIDI demandé.'}catch(e){report.textContent=e.message}finally{button.disabled=false}};
